1	//! Manifest reading and MatrixReport assembly for `callisto matrix`.
2	//! Private helpers only -- the public entry point is
3	//! `crate::commands::matrix::matrix`.
4	
5	/// Per-triple CI scheduling attributes for the 18 triples
6	/// `crate::napi::triple_to_role` recognises today. This table is NEW code:
7	/// `triple_to_role`'s `ManifestRole::Platform` carries only platform/arch/abi
8	/// and has no concept of hostRunner/useCross, so this cannot be derived from
9	/// it. Returns `None` for any triple `triple_to_role` does not recognise --
10	/// callers must treat that as the AC-011 diagnostic path, never a silent
11	/// default.
12	pub(crate) fn triple_host_runner_use_cross(triple: &str) -> Option<(&'static str, bool)> {
13	    Some(match triple {
14	        "aarch64-apple-darwin" => ("macos-latest", false),
15	        "x86_64-apple-darwin" => ("macos-13", false),
16	        "x86_64-unknown-linux-gnu" => ("ubuntu-latest", false),
17	        "x86_64-unknown-linux-musl" => ("ubuntu-latest", true),
18	        "aarch64-unknown-linux-gnu" => ("ubuntu-latest", true),
19	        "aarch64-unknown-linux-musl" => ("ubuntu-latest", true),
20	        "x86_64-pc-windows-msvc" => ("windows-latest", false),
21	        "i686-pc-windows-msvc" => ("windows-latest", false),
22	        "aarch64-pc-windows-msvc" => ("windows-latest", false),
23	        "armv7-unknown-linux-gnueabihf" => ("ubuntu-latest", true),
24	        "x86_64-unknown-freebsd" => ("ubuntu-latest", true),
25	        "aarch64-linux-android" => ("ubuntu-latest", true),
26	        "armv7-linux-androideabi" => ("ubuntu-latest", true),
27	        "riscv64gc-unknown-linux-gnu" => ("ubuntu-latest", true),
28	        "powerpc64le-unknown-linux-gnu" => ("ubuntu-latest", true),
29	        "s390x-unknown-linux-gnu" => ("ubuntu-latest", true),
30	        "wasm32-wasip1" => ("ubuntu-latest", false),
31	        "wasm32-unknown-unknown" => ("ubuntu-latest", false),
32	        _ => return None,
33	    })
34	}
35	
36	/// AC-013: artifactName is always the literal "native-" concatenated with
37	/// the triple string, for every recognised triple.
38	pub(crate) fn artifact_name_for_triple(triple: &str) -> String {
39	    format!("native-{triple}")
40	}
41	
42	use std::path::Path;
43	
44	use callisto_model::{ManifestError, ManifestFormat, ManifestRole, PlatformTarget};
45	
46	use crate::error::GraphError;
47	use crate::napi::triple_to_role;
48	
49	/// Result of reading the `napi.targets` field from a package.json. Distinct
50	/// from `Option<Vec<String>>` so AC-001b (present-but-empty vs absent) is a
51	/// type-level distinction, not a magic-empty-vec convention.
52	#[derive(Clone, Debug, PartialEq, Eq)]
53	pub(crate) enum NapiTargetsField {
54	    Absent,
55	    Present(Vec<String>),
56	}
57	
58	/// Reads and parses `pkg_json_path` as JSON, if it exists. `Ok(None)` when
59	/// the file is absent -- not every package has a `package.json`.
60	///
61	/// Callers needing more than one field out of the same `package.json` (e.g.
62	/// both `napi.targets` and `engines.node`, see `build_matrix_report`) must
63	/// call this once and pass the resulting `Value` to each field-extraction
64	/// function (`read_napi_targets`, `read_engines_node`) rather than letting
65	/// each one independently re-read and re-parse the file from disk.
66	pub(crate) fn parse_package_json(pkg_json_path: &Path) -> Result<Option<serde_json::Value>, GraphError> {
67	    if !pkg_json_path.exists() {
68	        return Ok(None);
69	    }
70	    let content = std::fs::read_to_string(pkg_json_path).map_err(|e| {
71	        GraphError::Manifest(ManifestError::Read {
72	            path: pkg_json_path.to_path_buf(),
73	            message: e.to_string(),
74	        })
75	    })?;
76	    let val: serde_json::Value = serde_json::from_str(&content).map_err(|e| {
77	        GraphError::Manifest(ManifestError::Parse {
78	            path: pkg_json_path.to_path_buf(),
79	            format: ManifestFormat::PackageJson,
80	            message: e.to_string(),
81	        })
82	    })?;
83	    Ok(Some(val))
84	}
85	
86	/// Extracts `napi.targets` from an already-parsed `package.json` value (see
87	/// `parse_package_json`). A missing `napi` key or missing `napi.targets` key
88	/// is `Absent` (AC-003: no platformTargets entry). A present `napi.targets`
89	/// that is not a JSON array of strings is a hard error (AC-010c) -- unlike
90	/// `NapiTargetsIndex::load`, which silently drops non-array values.
91	pub(crate) fn read_napi_targets(pkg_json_path: &Path, val: &serde_json::Value) -> Result<NapiTargetsField, GraphError> {
92	    let Some(napi) = val.get("napi") else {
93	        return Ok(NapiTargetsField::Absent);
94	    };
95	    let Some(targets) = napi.get("targets") else {
96	        return Ok(NapiTargetsField::Absent);
97	    };
98	
99	    let arr = targets.as_array().ok_or_else(|| {
100	        GraphError::Manifest(ManifestError::Parse {
101	            path: pkg_json_path.to_path_buf(),
102	            format: ManifestFormat::PackageJson,
103	            message: "napi.targets must be a JSON array of strings".to_string(),
104	        })
105	    })?;
106	
107	    let mut out = Vec::with_capacity(arr.len());
108	    for item in arr {
109	        let s = item.as_str().ok_or_else(|| {
110	            GraphError::Manifest(ManifestError::Parse {
111	                path: pkg_json_path.to_path_buf(),
112	                format: ManifestFormat::PackageJson,
113	                message: "napi.targets entries must all be strings".to_string(),
114	            })
115	        })?;
116	        out.push(s.to_string());
117	    }
118	    Ok(NapiTargetsField::Present(out))
119	}
120	
121	/// Builds a PlatformTarget for `triple`, combining `triple_to_role`'s
122	/// platform/arch/abi with this module's hostRunner/useCross/artifactName
123	/// table. Returns `None` when `triple` is not recognised by either --
124	/// callers must route that case to an UnrecognisedPlatformTriple diagnostic
125	/// (AC-011) rather than treating it as an error.
126	pub(crate) fn build_platform_target(triple: &str, package_dir: &str, package_name: &str) -> Option<PlatformTarget> {
127	    let ManifestRole::Platform { platform, arch, abi } = triple_to_role(triple)? else {
128	        return None;
129	    };
130	    let (host_runner, use_cross) = triple_host_runner_use_cross(triple)?;
131	    Some(PlatformTarget {
132	        triple: triple.to_string(),
133	        platform,
134	        arch,
135	        abi,
136	        host_runner: host_runner.to_string(),
137	        use_cross,
138	        artifact_name: artifact_name_for_triple(triple),
139	        package_dir: package_dir.to_string(),
140	        package_name: package_name.to_string(),
141	    })
142	}
143	
144	/// Reads and parses `pyproject_path` as TOML, if it exists. `Ok(None)` when
145	/// the file is absent -- not every package has a `pyproject.toml`.
146	///
147	/// Callers needing more than one field out of the same `pyproject.toml`
148	/// (e.g. both `[tool.maturin].targets` and `requires-python`, see
149	/// `build_matrix_report`) must call this once and pass the resulting
150	/// `Value` to each field-extraction function (`read_maturin_targets`,
151	/// `read_requires_python`) rather than letting each one independently
152	/// re-read and re-parse the file from disk.
153	pub(crate) fn parse_pyproject_toml(pyproject_path: &Path) -> Result<Option<toml::Value>, GraphError> {
154	    if !pyproject_path.exists() {
155	        return Ok(None);
156	    }
157	    let content = std::fs::read_to_string(pyproject_path).map_err(|e| {
158	        GraphError::Manifest(ManifestError::Read {
159	            path: pyproject_path.to_path_buf(),
160	            message: e.to_string(),
161	        })
162	    })?;
163	    let val: toml::Value = content.parse().map_err(|e: toml::de::Error| {
164	        GraphError::Manifest(ManifestError::Parse {
165	            path: pyproject_path.to_path_buf(),
166	            format: ManifestFormat::PyprojectToml,
167	            message: e.to_string(),
168	        })
169	    })?;
170	    Ok(Some(val))
171	}
172	
173	/// Extracts `[tool.maturin].targets` from an already-parsed `pyproject.toml`
174	/// value (see `parse_pyproject_toml`). Returns `Ok(None)` when the table or
175	/// field is absent (AC-003: no platformTargets entry). A present value that
176	/// is not a TOML array of strings is a hard error (AC-010c).
177	pub(crate) fn read_maturin_targets(
178	    pyproject_path: &Path,
179	    val: &toml::Value,
180	) -> Result<Option<Vec<String>>, GraphError> {
181	    let Some(targets) = val
182	        .get("tool")
183	        .and_then(|t| t.get("maturin"))
184	        .and_then(|m| m.get("targets"))
185	    else {
186	        return Ok(None);
187	    };
188	
189	    let arr = targets.as_array().ok_or_else(|| {
190	        GraphError::Manifest(ManifestError::Parse {
191	            path: pyproject_path.to_path_buf(),
192	            format: ManifestFormat::PyprojectToml,
193	            message: "[tool.maturin].targets must be an array of strings".to_string(),
194	        })
195	    })?;
196	
197	    let mut out = Vec::with_capacity(arr.len());
198	    for item in arr {
199	        let s = item.as_str().ok_or_else(|| {
200	            GraphError::Manifest(ManifestError::Parse {
201	                path: pyproject_path.to_path_buf(),
202	                format: ManifestFormat::PyprojectToml,
203	                message: "[tool.maturin].targets entries must all be strings".to_string(),
204	            })
205	        })?;
206	        out.push(s.to_string());
207	    }
208	    Ok(Some(out))
209	}
210	
211	/// Extracts `engines.node` as a raw string from an already-parsed
212	/// `package.json` value (see `parse_package_json`). `Ok(None)` when absent;
213	/// `Err` when present but not a JSON string.
214	pub(crate) fn read_engines_node(pkg_json_path: &Path, val: &serde_json::Value) -> Result<Option<String>, GraphError> {
215	    let Some(node) = val.get("engines").and_then(|e| e.get("node")) else {
216	        return Ok(None);
217	    };
218	    let s = node.as_str().ok_or_else(|| {
219	        GraphError::Manifest(ManifestError::Parse {
220	            path: pkg_json_path.to_path_buf(),
221	            format: ManifestFormat::PackageJson,
222	            message: "engines.node must be a string".to_string(),
223	        })
224	    })?;
225	    Ok(Some(s.to_string()))
226	}
227	
228	/// Extracts `requires-python` as a raw string from an already-parsed
229	/// `pyproject.toml` value (see `parse_pyproject_toml`). `Ok(None)` when
230	/// absent; `Err` when present but not a TOML string.
231	pub(crate) fn read_requires_python(pyproject_path: &Path, val: &toml::Value) -> Result<Option<String>, GraphError> {
232	    let Some(rp) = val.get("project").and_then(|p| p.get("requires-python")) else {
233	        return Ok(None);
234	    };
235	    let s = rp.as_str().ok_or_else(|| {
236	        GraphError::Manifest(ManifestError::Parse {
237	            path: pyproject_path.to_path_buf(),
238	            format: ManifestFormat::PyprojectToml,
239	            message: "requires-python must be a string".to_string(),
240	        })
241	    })?;
242	    Ok(Some(s.to_string()))
243	}
244	
245	use callisto_model::{PackageId, PlatformTargetKind};
246	
247	/// Reads napi.targets and [tool.maturin].targets from `package_dir_abs`
248	/// (the package's on-disk directory) and determines which single source (if
249	/// any) declares platform targets.
250	///
251	/// `pkg_json_val`/`pyproject_val` are the package's already-parsed manifest
252	/// values (see `parse_package_json`/`parse_pyproject_toml`), `None` when the
253	/// corresponding file doesn't exist -- shared with `assemble_runtime_versions`
254	/// so `build_matrix_report` parses each file at most once per package.
255	///
256	/// - Neither declared: `Ok(None)` (AC-003).
257	/// - Both declared: `Err(GraphError::ConflictingPlatformTargetSources)` (AC-017).
258	/// - Exactly one declared (even as an explicitly empty array, AC-001b):
259	///   `Ok(Some((kind, source, triples)))`.
260	pub(crate) fn select_platform_target_source(
261	    package_dir_abs: &Path,
262	    package_id: &PackageId,
263	    pkg_json_val: Option<&serde_json::Value>,
264	    pyproject_val: Option<&toml::Value>,
265	) -> Result<Option<(PlatformTargetKind, String, Vec<String>)>, GraphError> {
266	    let napi_path = package_dir_abs.join("package.json");
267	    let napi_field = match pkg_json_val {
268	        Some(val) => read_napi_targets(&napi_path, val)?,
269	        None => NapiTargetsField::Absent,
270	    };
271	
272	    let maturin_path = package_dir_abs.join("pyproject.toml");
273	    let maturin_targets = match pyproject_val {
274	        Some(val) => read_maturin_targets(&maturin_path, val)?,
275	        None => None,
276	    };
277	
278	    match (napi_field, maturin_targets) {
279	        (NapiTargetsField::Present(_), Some(_)) => Err(GraphError::ConflictingPlatformTargetSources {
280	            package: package_id.clone(),
281	            napi_source: "napi.targets",
282	            maturin_source: "[tool.maturin].targets",
283	        }),
284	        (NapiTargetsField::Present(triples), None) => {
285	            Ok(Some((PlatformTargetKind::Napi, "napi.targets".to_string(), triples)))
286	        }
287	        (NapiTargetsField::Absent, Some(triples)) => Ok(Some((
288	            PlatformTargetKind::Maturin,
289	            "[tool.maturin].targets".to_string(),
290	            triples,
291	        ))),
292	        (NapiTargetsField::Absent, None) => Ok(None),
293	    }
294	}
